"""Migrated validation rules from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _field(row: dict | None, name: str) -> Any:
    """Return a field value, with missing fields represented by the legacy empty string."""
    if row is None:
        return ""
    return row.get(name, "")


def _nvl(value: Any, default: Any) -> Any:
    """Implement legacy NVL: empty, missing, and None use the default."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Implement legacy numeric coercion, where empty values compare as zero."""
    value = _nvl(value, 0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_ge(left: Any, right: Any) -> bool:
    """Compare legacy YYYYMMDD dates, respecting the 00000000 null sentinel."""
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using legacy VRL rule order."""
    errors: list[dict] = []

    amt = _field(record, "AMT")
    stat_cd = _field(record, "STAT_CD")
    lost_rsn = _field(record, "LOST_RSN")
    close_dt = _field(record, "CLOSE_DT")
    stage_pct = _field(record, "STAGE_PCT")

    # OPP-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amt, 0)) >= Decimal(0)):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0))):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005: UPDATE
    if event == "UPDATE":
        old_stat_cd = _field(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        stage_pct_num = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage_pct_num == Decimal(10))
            or (stat_cd == "Q" and stage_pct_num == Decimal(25))
            or (stat_cd == "N" and stage_pct_num == Decimal(60))
            or (stat_cd == "W" and stage_pct_num == Decimal(100))
            or (stat_cd == "L" and stage_pct_num == Decimal(0))
        )
        if not valid_stage:
            errors.append(_error("E3006", "Stage percent inconsistent with status"))

    # OPP-007: INSERT
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append(_error("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
